import { useState } from "react";
import { Card } from "@/shared/ui/data/Card";
import { Button } from "@/shared/ui/controls/Button";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Row } from "@/shared/ui/layout/Row";
import { Toggle } from "@/shared/ui/controls/Toggle";

// Vendored from `@/features/settings/pages/SettingsControls` (unresolvable in this sandbox for these
// two — only ToggleRow itself is separately registered) — unchanged.
function ToggleRow({ on, onToggle, title, children }) {
  return (
    <Row gap={12}>
      <Toggle on={on} onClick={onToggle} role="switch" ariaChecked={on} />
      <Box>
        <Text as="div" mono size={11.5} style={{ color: "var(--fg)", marginBottom: 2 }}>
          {title}
        </Text>
        <Box className="hint">{children}</Box>
      </Box>
    </Row>
  );
}
function SettingsRow({ label, hint, children }) {
  return (
    <Row gap={12} style={{ padding: "10px 0", borderBottom: "1px solid var(--border-soft)" }}>
      <Box style={{ flex: 1, minWidth: 0 }}>
        <Text as="div" size={13} style={{ fontFamily: "var(--sans)", color: "var(--fg)" }}>{label}</Text>
        {hint && <Text as="div" size={11} tone="dim" style={{ fontFamily: "var(--sans)", marginTop: 2 }}>{hint}</Text>}
      </Box>
      {children}
    </Row>
  );
}
function SettingsSelect({ value, options, onChange }) {
  return (
    // eslint-disable-next-line no-restricted-syntax -- helper intentionally renders a bespoke compact mono <select> (type-preserving onChange) for settings rows; not a .field stack
    <select
      value={value}
      onChange={(e) => { const raw = e.target.value; onChange(typeof value === "number" ? Number(raw) : raw); }}
      className="mono"
      style={{ fontSize: 11.5, background: "var(--bg-elev)", color: "var(--fg)", border: "1px solid var(--border)", borderRadius: 6, padding: "5px 8px", cursor: "pointer" }}
    >
      {options.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
    </select>
  );
}

// Vendored from `@/shared/lib/a11y/speech` (unresolvable in this sandbox) — unchanged: these wrap the
// REAL WebView SpeechSynthesis browser API (not an app-internal dependency), and guard for its absence.
function synth() {
  if (typeof window === "undefined") return null;
  return window.speechSynthesis ?? null;
}
function isSpeechSupported() {
  return synth() !== null && typeof SpeechSynthesisUtterance !== "undefined";
}
function listVoices() {
  return synth()?.getVoices() ?? [];
}
function speak(text, opts = {}) {
  const s = synth();
  if (!s || !isSpeechSupported() || !text.trim()) return;
  const u = new SpeechSynthesisUtterance(text);
  if (opts.rate != null) u.rate = opts.rate;
  if (opts.voiceURI) {
    const v = s.getVoices().find((voice) => voice.voiceURI === opts.voiceURI);
    if (v) u.voice = v;
  }
  s.speak(u);
}

export function TtsCard() {
  const [ttsEnabled, setTtsEnabled] = useState(false);
  const [ttsRate, setTtsRate] = useState(1);
  const [ttsVoice, setTtsVoice] = useState("");
  const [ttsVerbosity, setTtsVerbosity] = useState("terse");
  const supported = isSpeechSupported();
  const voices = supported ? listVoices() : [];

  return (
    <Card title="Spoken coordination" hint="opt-in — off by default">
      <ToggleRow
        on={ttsEnabled}
        onToggle={() => setTtsEnabled(!ttsEnabled)}
        title="Speak fleet coordination events aloud"
      >
        Reads <b>new</b> coordination events aloud — a worker pausing for you, a question to answer, a PR
        landing — so you can drive the fleet <b>by ear</b>. It speaks the structured events, never the raw
        terminal stream. Separate from your screen reader; nothing is spoken until you enable it.
      </ToggleRow>

      {!supported && (
        <Text as="div" size={11} tone="dim" style={{ marginTop: 10 }}>
          Text-to-speech isn't available in this environment.
        </Text>
      )}

      {ttsEnabled && supported && (
        <Box style={{ marginTop: 12 }}>
          <SettingsRow label="Verbosity" hint="terse speaks only what needs you; verbose adds progress (landings, ready gates)">
            <SettingsSelect
              value={ttsVerbosity}
              options={[{ label: "Terse", value: "terse" }, { label: "Verbose", value: "verbose" }]}
              onChange={(v) => setTtsVerbosity(v)}
            />
          </SettingsRow>
          <SettingsRow label="Rate" hint="speech speed">
            <SettingsSelect
              value={ttsRate}
              options={[
                { label: "0.75×", value: 0.75 }, { label: "1×", value: 1 }, { label: "1.25×", value: 1.25 },
                { label: "1.5×", value: 1.5 }, { label: "1.75×", value: 1.75 },
              ]}
              onChange={(v) => setTtsRate(Number(v))}
            />
          </SettingsRow>
          <SettingsRow label="Voice" hint="the platform voice used">
            <SettingsSelect
              value={ttsVoice}
              options={[{ label: "Default", value: "" }, ...voices.map((v) => ({ label: `${v.name} (${v.lang})`, value: v.voiceURI }))]}
              onChange={(v) => setTtsVoice(String(v))}
            />
          </SettingsRow>
          <Box style={{ marginTop: 10 }}>
            <Button
              variant="ghost"
              onClick={() => speak("Worker api-stream is paused, waiting for you.", { rate: ttsRate, voiceURI: ttsVoice || undefined })}
            >
              Test voice
            </Button>
          </Box>
        </Box>
      )}
    </Card>
  );
}
